//! 🔀️ Original reorder validation compares two independently retained sorted key tables through bounded heap-sort work.
use super::*;
use semio_framework_value_edit::{HeapSortCursor,HeapSortWork};
/// 🧭️ A permutation path lends fixed original keys from the authored vector and selected row.
pub trait OriginalPermutationPath:OwnedRowPath{fn input_len(v:&Self::Value)->usize;fn input_key(v:&Self::Value,index:usize)->u32;fn held_len(r:&Self::Row)->usize;fn held_key(r:&Self::Row,index:usize)->u32;}
pub struct PermutationValidation<S:OriginalPermutationPath>{input:Option<RetainedCloneBinding>,row:Option<RetainedCloneBinding>,body:Option<usize>,wanted:ManuallyDrop<Option<Vec<u32>>>,held:ManuallyDrop<Option<Vec<u32>>>,sort:HeapSortCursor,index:usize,phase:u8,finished:bool,mismatch:bool,closing:bool,retirement:RetainedCloneClose,marker:std::marker::PhantomData<fn()->S>}
impl<S:OriginalPermutationPath> PermutationValidation<S>{pub fn new()->Self{Self{input:None,row:None,body:None,wanted:ManuallyDrop::new(None),held:ManuallyDrop::new(None),sort:HeapSortCursor::new(0),index:0,phase:0,finished:false,mismatch:false,closing:false,retirement:Default::default(),marker:Default::default()}}}
impl<S:OriginalPermutationPath> OwnedRowValidation<S::Value,S::Row> for PermutationValidation<S>{
 fn demand(&self,v:RetainedCloneRef<'_,S::Value>,_:RetainedCloneRef<'_,u32>,_:RetainedCloneRef<'_,EnergyModelSnapshot>,r:RetainedCloneRef<'_,S::Row>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.finished||self.body.is_some_and(|b|b!=body){return Err(invalid());}v.check_binding(&self.input)?;r.check_binding(&self.row)?;match self.phase{0=>nested(scalar(v.binding_copy_bytes()+size_of::<usize>()),1),1=>nested(scalar(r.binding_copy_bytes()),1),2=>Ok(scalar(6*size_of::<usize>()+2)),3|7=>Ok(RetirementDemand{copy_bytes:2*size_of::<Option<Vec<u32>>>()+1,capacity_bytes:S::input_len(v.get()).checked_mul(size_of::<u32>()).ok_or_else(invalid)?,depth:1,..Default::default()}),4|8|11=>Ok(scalar(4*size_of::<u32>()+4*size_of::<usize>()+4)),5|6|9|10=>Ok(scalar(2*size_of::<HeapSortCursor>()+4*size_of::<u32>()+4*size_of::<usize>()+1)),_=>Err(invalid())}}
 fn advance(&mut self,v:RetainedCloneRef<'_,S::Value>,key:RetainedCloneRef<'_,u32>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,r:RetainedCloneRef<'_,S::Row>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(v,key,o,r,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut p=receipt(d);match self.phase{
 0=>{p=add(v.bind(&mut self.input,child(g,1+size_of::<usize>()))?.ok_or_else(invalid)?,1+size_of::<usize>())?;self.body=Some(body);self.phase=1;},1=>{p=add(r.bind(&mut self.row,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=2;},2=>{if S::input_len(v.get())!=S::held_len(r.get()){self.finished=true;self.mismatch=true;}else{self.phase=3;}},3=>{let values=Vec::with_capacity(S::input_len(v.get()));p.retained_capacity_bytes=values.capacity()*size_of::<u32>();*self.wanted=Some(values);self.phase=4;},4=>{if self.index==S::input_len(v.get()){self.phase=5;}else{self.wanted.as_mut().ok_or_else(invalid)?.push(S::input_key(v.get(),self.index));self.index+=1;}},5|9=>{self.sort=HeapSortCursor::new(S::input_len(v.get()));self.phase+=1;},6|10=>{let values=if self.phase==6{self.wanted.as_mut()}else{self.held.as_mut()}.ok_or_else(invalid)?;match self.sort.next(){HeapSortWork::Compare{left,right}=>self.sort.advance(Some(values[left].cmp(&values[right]))).map_err(|_|invalid())?,HeapSortWork::Swap{left,right}=>{values.swap(left,right);self.sort.advance(None).map_err(|_|invalid())?;},HeapSortWork::Advance=>self.sort.advance(None).map_err(|_|invalid())?,HeapSortWork::Complete=>{self.index=0;self.phase+=1;}}},7=>{let values=Vec::with_capacity(S::held_len(r.get()));p.retained_capacity_bytes=values.capacity()*size_of::<u32>();*self.held=Some(values);self.phase=8;},8=>{if self.index==S::held_len(r.get()){self.phase=9;}else{self.held.as_mut().ok_or_else(invalid)?.push(S::held_key(r.get(),self.index));self.index+=1;}},11=>{if self.index==S::input_len(v.get()){self.finished=true;}else if self.wanted.as_ref().ok_or_else(invalid)?[self.index]!=self.held.as_ref().ok_or_else(invalid)?[self.index]{self.finished=true;self.mismatch=true;}else{self.index+=1;}},_=>return Err(invalid())}semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"original layer permutation keys and heap-sort work")?;Ok(if self.finished{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn result(&self)->Option<Option<RowOutcome>>{self.finished.then_some(self.mismatch.then_some(RowOutcome::InvalidContext))}
 fn begin_close(&mut self){self.closing=true;}
}
impl<S:OriginalPermutationPath> CursorClose for PermutationValidation<S>{
 fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}self.retirement.next_owner_demands::<Vec<u32>>(self.wanted.is_some()||self.held.is_some(),if self.input.is_some(){&self.input}else{&self.row},self.body.unwrap_or(body))}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let body=self.body.unwrap_or(g.maximum_copy_bytes);let d=self.close_demand(body)?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let g=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes,..g};if !self.retirement.is_empty(){return self.retirement.select(body)?.step(g);}if let Some(s)=self.retirement.begin_granted(&mut self.wanted,g)?{return Ok(s);}if let Some(s)=self.retirement.begin_granted(&mut self.held,g)?{return Ok(s);}let s=RetainedCloneBinding::close_one(if self.input.is_some(){&mut self.input}else{&mut self.row},g)?;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(s.progress())}else{RetainedCloneStep::Progress(s.progress())})}
 fn terminal_is_empty(&self)->bool{self.closing&&self.input.is_none()&&self.row.is_none()&&self.wanted.is_none()&&self.held.is_none()&&self.retirement.is_empty()}
}
impl<S:OriginalPermutationPath> Drop for PermutationValidation<S>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"original permutation retains sort keys or source authority");if empty{unsafe{ManuallyDrop::drop(&mut self.wanted);ManuallyDrop::drop(&mut self.held);}}}}
